# --- the table -----------------------------------------------------------------------------------------------

class Table:
    """Column names and rows of strings. `source` names where it came from, for messages."""

    def __init__(self, columns, rows, source="<table>"):
        self.columns = list(columns)
        self.rows = [list(r) for r in rows]
        self.source = source

    def __len__(self):
        return len(self.rows)

    def index(self, name):
        """Position of a column; TabulaError when there is none."""
        try:
            return self.columns.index(name)
        except ValueError:
            raise TabulaError("%s: no column %r (columns: %s)" % (self.source, name, ", ".join(self.columns)))

    def column(self, name):
        at = self.index(name)
        return [row[at] for row in self.rows]

    def dicts(self):
        return [dict(zip(self.columns, row)) for row in self.rows]

    def with_rows(self, rows, columns=None):
        return Table(self.columns if columns is None else columns, rows, self.source)


def parse_text(text, source):
    """CSV text into a Table. Blank lines are ignored; every row must have as many fields as the header."""
    if text.startswith("﻿"):
        text = text[1:]
    reader = csv.reader(io.StringIO(text, newline=""))
    columns, rows = None, []
    try:
        for fields in reader:
            if not fields:
                continue
            if columns is None:
                for name in fields:
                    if not name.strip():
                        raise TabulaError("%s: line %d: empty column name" % (source, reader.line_num))
                if len(set(fields)) != len(fields):
                    raise TabulaError("%s: line %d: duplicate column name" % (source, reader.line_num))
                columns = fields
                continue
            if len(fields) != len(columns):
                raise TabulaError("%s: line %d: expected %d fields, found %d"
                                  % (source, reader.line_num, len(columns), len(fields)))
            rows.append(fields)
    except csv.Error as exc:
        raise TabulaError("%s: line %d: %s" % (source, reader.line_num, exc))
    if columns is None:
        raise TabulaError("%s: no header line" % source)
    return Table(columns, rows, source)


def load(path):
    """Read a CSV file (UTF-8, optional byte order mark, LF or CRLF) into a Table."""
    try:
        with open(path, "rb") as fh:
            raw = fh.read()
    except OSError as exc:
        raise TabulaError("%s: cannot read: %s" % (path, exc.strerror or exc))
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        raise TabulaError("%s: not valid UTF-8" % path)
    return parse_text(text, path)


# --- output --------------------------------------------------------------------------------------------------

def render_text(table):
    cells = [table.columns] + table.rows
    widths = [max(len(row[i]) for row in cells) for i in range(len(table.columns))]
    lines = ["  ".join(cell.ljust(width) for cell, width in zip(row, widths)).rstrip() for row in cells]


# --- commands ------------------------------------------------------------------------------------------------

def _need_args(args, count, usage):
    if len(args) != count:
        raise UsageError("usage: %s %s" % (PROG, usage))


def _need_at_least(args, count, usage):
    if len(args) < count:
        raise UsageError("usage: %s %s" % (PROG, usage))


def _cell_number(table, row_number, column, value):
    """The Decimal in a cell; TabulaError naming the file, the data row (1-based, file order) and the column."""
    number = to_decimal(value)
    if number is None:
        raise TabulaError("%s: row %d: column %r: %r is not a number" % (table.source, row_number, column, value))
    return number


def cmd_show(args, opts):
    _need_args(args, 1, "show FILE")
    return load(args[0])


def cmd_head(args, opts):
    _need_args(args, 2, "head FILE N")
    if not args[1].isdigit():
        raise UsageError("head: N must be a whole number, got %r" % args[1])
    table = load(args[0])
    return table.with_rows(table.rows[:int(args[1])])


def cmd_cols(args, opts):
    _need_args(args, 1, "cols FILE")
    table = load(args[0])
    return Table(["position", "column"], [[str(i + 1), name] for i, name in enumerate(table.columns)], table.source)


def cmd_apply(args, opts):
    _need_at_least(args, 3, "apply FILE COLUMN TRANSFORM...")
    table = load(args[0])
    at = table.index(args[1])
    specs = [parse_spec(s) for s in args[2:]]
    rows = []
    for number, row in enumerate(table.rows, 1):
        row = list(row)
        try:
            row[at] = apply_transforms(row[at], specs)
        except TabulaError as exc:
            raise TabulaError("%s: row %d: %s" % (table.source, number, exc))
        rows.append(row)
    return table.with_rows(rows)


def _parse_key(text):
    """(column, numeric, descending) from COLUMN[:num][:desc]; UsageError when a modifier is wrong."""
    column, *mods = text.split(":")
    numeric = descending = False
    for mod in mods:
        if mod == "num" and not numeric:
            numeric = True
        elif mod == "desc" and not descending:
            descending = True
        else:
            raise UsageError("sort: bad modifier %r in key %r (use :num and :desc, each once)" % (mod, text))
    return column, numeric, descending


def cmd_sort(args, opts):
    _need_at_least(args, 2, "sort FILE KEY...")
    keys = [_parse_key(k) for k in args[1:]]
    table = load(args[0])
    wanted = [(table.index(column), column, numeric, descending) for column, numeric, descending in keys]
    numbered = list(enumerate(table.rows, 1))
    # numeric keys are checked cell by cell, in file order, before anything moves
    numeric_keys = [(at, column) for at, column, numeric, _ in wanted if numeric]
    numbers = {at: {} for at, _ in numeric_keys}
    for n, row in numbered:
        for at, column in numeric_keys:
            numbers[at][n] = _cell_number(table, n, column, row[at])
    for at, column, numeric, descending in reversed(wanted):
        if numeric:
            lookup = numbers[at]
            numbered.sort(key=lambda item: lookup[item[0]], reverse=descending)
        else:
            numbered.sort(key=lambda item: item[1][at], reverse=descending)
    return table.with_rows([row for _, row in numbered])


FILTER_OPERATORS = ("==", "!=", ">=", "<=", ">", "<", "~")


def _parse_condition(text):
    """(column, operator, value) from COLUMN OP VALUE; UsageError when there is no operator or no column."""
    for at in range(len(text)):
        for op in FILTER_OPERATORS:
            if text.startswith(op, at):
                if at == 0:
                    raise UsageError("filter: no column before the operator in condition %r" % text)
                return text[:at], op, text[at + len(op):]
    raise UsageError("filter: no operator in condition %r (use one of %s)" % (text, ", ".join(FILTER_OPERATORS)))


def _holds(cell, op, value, number):
    """Whether one cell passes one condition; `number` is the Decimal of VALUE, or None when it is not a number."""
    if op == "~":
        return value.casefold() in cell.casefold()
    left = to_decimal(cell) if number is not None else None
    if left is None:
        left, right = cell, value
    else:
        right = number
    return {"==": left == right, "!=": left != right, ">=": left >= right,
            "<=": left <= right, ">": left > right, "<": left < right}[op]


def cmd_filter(args, opts):
    _need_at_least(args, 2, "filter FILE CONDITION...")
    conditions = [_parse_condition(c) for c in args[1:]]
    table = load(args[0])
    wanted = [(table.index(column), op, value, to_decimal(value)) for column, op, value in conditions]
    return table.with_rows([row for row in table.rows
                            if all(_holds(row[at], op, value, number) for at, op, value, number in wanted)])


GROUP_NUMERIC = ("sum", "min", "max", "mean")


def _parse_aggregate(text):
    """(name, column or None) from `count` or `NAME:COLUMN`; UsageError when it is neither."""
    name, colon, column = text.partition(":")
    if text == "count" or (colon and column and name in GROUP_NUMERIC):
        return name, (column if colon else None)
    raise UsageError("group: bad aggregate %r (use count, sum:COLUMN, min:COLUMN, max:COLUMN or mean:COLUMN)" % text)


def cmd_group(args, opts):
    _need_at_least(args, 3, "group FILE BY AGGREGATE...")
    if len(set(args[2:])) != len(args[2:]):
        dup = next(a for i, a in enumerate(args[2:]) if a in args[2:i + 2])
        raise UsageError("group: aggregate %r given twice" % dup)
    aggregates = [_parse_aggregate(a) for a in args[2:]]
    table = load(args[0])
    by = table.index(args[1])
    wanted = [(name, None if column is None else (table.index(column), column)) for name, column in aggregates]
    names = [args[1]] + [a.replace(":", "_") for a in args[2:]]
    for name in names:
        if names.count(name) > 1:
            raise TabulaError("result would have column %r twice" % name)
    groups = {}
    for n, row in enumerate(table.rows, 1):
        members = groups.setdefault(row[by], [])
        members.append([None if w is None else _cell_number(table, n, w[1], row[w[0]]) for _, w in wanted])
    # sums of long numbers must stay exact: size the precision to the longest cell
    digits = max([len(c) for row in table.rows for c in row] + [28]) + len(str(len(table.rows))) + 30
    rows = []
    with localcontext() as ctx:
        ctx.prec = digits
        for key, members in groups.items():
            out = [key]
            for i, (name, _) in enumerate(wanted):
                values = [m[i] for m in members]
                if name == "count":
                    out.append(str(len(members)))
                elif name == "sum":
                    out.append(fmt_decimal(sum(values, Decimal(0))))
                elif name == "min":
                    out.append(fmt_decimal(min(values)))
                elif name == "max":
                    out.append(fmt_decimal(max(values)))
                else:
                    out.append(fmt_2dp(sum(values, Decimal(0)) / len(values)))
            rows.append(out)
    return Table(names, rows, table.source)


COMMANDS = {
    "show": (cmd_show, "show FILE", "print a table"),
    "head": (cmd_head, "head FILE N", "the first N rows"),
    "cols": (cmd_cols, "cols FILE", "the column names, numbered"),
    "apply": (cmd_apply, "apply FILE COLUMN TRANSFORM...", "run transforms over one column"),
    "sort": (cmd_sort, "sort FILE KEY...", "rows sorted by one or more columns"),
    "filter": (cmd_filter, "filter FILE CONDITION...", "rows where every condition holds"),
    "group": (cmd_group, "group FILE BY AGGREGATE...", "one row per value of a column, with aggregates"),
}


# --- the command line ----------------------------------------------------------------------------------------

def usage_text():
    lines = ["usage: %s [--format text|csv|json] [--kind inner|left] [--keep first|last] COMMAND ARGS..." % PROG,
             "", "commands:"]
    width = max(len(u) for _, u, _ in COMMANDS.values())
    for _, use, what in COMMANDS.values():
        lines.append("  %s  %s" % (use.ljust(width), what))
    return "\n".join(lines) + "\n"


def parse_args(argv):
    """(command, positional arguments, options) from the command line."""
    opts, rest, i = dict(DEFAULTS), [], 0
    while i < len(argv):
        arg = argv[i]
        name = arg[2:].split("=", 1)[0] if arg.startswith("--") else None
        if arg in ("-h", "--help"):
            opts["help"] = True
        elif name in OPTIONS:
            if "=" in arg:
                value = arg.split("=", 1)[1]
            else:
                i += 1
                if i >= len(argv):
                    raise UsageError("--%s needs a value" % name)
                value = argv[i]
            if value not in OPTIONS[name]:
                raise UsageError("--%s must be one of %s, got %r" % (name, ", ".join(OPTIONS[name]), value))
            opts[name] = value
        elif arg.startswith("-") and len(arg) > 1:
            raise UsageError("unknown option %s" % arg)
        else:
            rest.append(arg)
        i += 1
    if opts.get("help"):
        return None, rest, opts
    if not rest:
        raise UsageError("no command given")
    if rest[0] not in COMMANDS:
        raise UsageError("unknown command %r" % rest[0])
    return rest[0], rest[1:], opts


def main(argv=None):
    argv = sys.argv[1:] if argv is None else list(argv)
    try:
        name, args, opts = parse_args(argv)
        if name is None:
            sys.stdout.write(usage_text())
            return 0
        table = COMMANDS[name][0](args, opts)
        sys.stdout.write(render(table, opts["format"]))
        sys.stdout.flush()
        return 0
    except UsageError as exc:
        print("%s: %s" % (PROG, exc), file=sys.stderr)
        return 2
    except TabulaError as exc:
        print("%s: %s" % (PROG, exc), file=sys.stderr)
        return 1
    except BrokenPipeError:
        return 0
    except OSError as exc:
        # the output could not be written (a full disk, say); the rest of it must not be flushed again at exit
        try:
            os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
        except (OSError, ValueError):
            pass
        print("%s: cannot write output: %s" % (PROG, exc.strerror or exc), file=sys.stderr)
        return 1

