import json, os, subprocess, sys, tempfile, unittest

ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..')

SALES = 'city,qty,price\nLeeds,10.50,2\nYork,2,x\nLeeds,+5,1.5\nHull,1.25,3\nYork,2.5,1\n'
NUMS = 'k,v\na,10.50\na,-0.5\nb,0.10\nb,0.05\nc,1.005\nc,1.005\n'


class GroupTests(unittest.TestCase):
    def run_cli(self, *argv, files=None):
        with tempfile.TemporaryDirectory() as d:
            for k, v in (files or {}).items():
                with open(os.path.join(d, k), 'w', encoding='utf-8', newline='') as fh:
                    fh.write(v)
            p = subprocess.run([sys.executable, '-m', 'tabula'] + list(argv), cwd=d, env=dict(os.environ, PYTHONPATH=ROOT),
                               capture_output=True, text=True)
            return p.returncode, p.stdout, p.stderr

    def check(self, argv, rc, out, err=None, files=None):
        out = '' if out is None else out
        got_rc, got_out, got_err = self.run_cli(*argv, files=files or {'t.csv': SALES})
        self.assertEqual((got_rc, got_out), (rc, out), got_err)
        self.assertEqual(bool(got_err), rc != 0)
        if err is not None:
            self.assertEqual(got_err, 'tabula: %s\n' % err)

    def test_aggregates_text(self):
        self.check(['group', 't.csv', 'city', 'count', 'sum:qty', 'min:qty', 'max:qty', 'mean:qty'], 0,
                   'city   count  sum_qty  min_qty  max_qty  mean_qty\n'
                   'Leeds  2      15.50    5        10.50    7.75\n'
                   'York   2      4.5      2        2.5      2.25\n'
                   'Hull   1      1.25     1.25     1.25     1.25\n')

    def test_formats(self):
        argv = ['group', 't.csv', 'city', 'count', 'sum:qty']
        self.check(['--format', 'csv'] + argv, 0, 'city,count,sum_qty\nLeeds,2,15.50\nYork,2,4.5\nHull,1,1.25\n')
        rc, out, err = self.run_cli('--format=json', *argv, files={'t.csv': SALES})
        self.assertEqual((rc, err), (0, ''))
        rows = json.loads(out)
        self.assertEqual([r['city'] for r in rows], ['Leeds', 'York', 'Hull'])
        self.assertEqual(rows[0], {'city': 'Leeds', 'count': '2', 'sum_qty': '15.50'})

    def test_first_appearance_order_and_exact_text_keys(self):
        self.check(['--format=csv', 'group', 't.csv', 'k', 'count'], 0, 'k,count\nb,2\nB,1\n,1\n b,1\n',
                   files={'t.csv': 'k\nb\nB\nb\n""\n b\n'})

    def test_number_output_and_mean_rounding(self):
        self.check(['--format=csv', 'group', 't.csv', 'k', 'sum:v', 'min:v', 'max:v', 'mean:v'], 0,
                   'k,sum_v,min_v,max_v,mean_v\na,10.00,-0.5,10.50,5.00\nb,0.15,0.05,0.10,0.08\nc,2.010,1.005,1.005,1.01\n',
                   files={'t.csv': NUMS})
        self.check(['--format=csv', 'group', 't.csv', 'k', 'mean:v'], 0, 'k,mean_v\na,-0.01\nb,0.00\nc,1.00\n',
                   files={'t.csv': 'k,v\na,-0.005\nb,0.004\nc,1\n'})

    def test_no_negative_zero_and_no_exponent(self):
        self.check(['--format=csv', 'group', 't.csv', 'k', 'sum:v', 'mean:v', 'min:v'], 0,
