    wanted = [(table.index(column), column, numeric, descending) for column, numeric, descending in keys]
    numbered = list(enumerate(table.rows, 1))
    # numeric keys are checked cell by cell, in file order, before anything moves
    numeric_keys = [(at, column) for at, column, numeric, _ in wanted if numeric]
    numbers = {at: {} for at, _ in numeric_keys}
    for n, row in numbered:
