FILTER_OPERATORS = ("==", "!=", ">=", "<=", ">", "<", "~")


def _parse_condition(text):
    """(column, operator, value) from COLUMN OP VALUE; UsageError when there is no operator or no column."""
    for at in range(len(text)):
        for op in FILTER_OPERATORS:
            if text.startswith(op, at):
                if at == 0:
                    raise UsageError("filter: no column before the operator in condition %r" % text)
                return text[:at], op, text[at + len(op):]
    raise UsageError("filter: no operator in condition %r (use one of %s)" % (text, ", ".join(FILTER_OPERATORS)))


def _holds(cell, op, value, number):
    """Whether one cell passes one condition; `number` is the Decimal of VALUE, or None when it is not a number."""
    if op == "~":
        return value.casefold() in cell.casefold()
    left = to_decimal(cell) if number is not None else None
    if left is None:
        left, right = cell, value
    else:
        right = number
    return {"==": left == right, "!=": left != right, ">=": left >= right,
            "<=": left <= right, ">": left > right, "<": left < right}[op]


