    _need_at_least(args, 2, "filter FILE CONDITION...")
    conditions = [_parse_condition(c) for c in args[1:]]
    table = load(args[0])
    wanted = [(table.index(column), op, value, to_decimal(value)) for column, op, value in conditions]
    return table.with_rows([row for row in table.rows
                            if all(_holds(row[at], op, value, number) for at, op, value, number in wanted)])


GROUP_NUMERIC = ("sum", "min", "max", "mean")


def _parse_aggregate(text):
    """(name, column or None) from `count` or `NAME:COLUMN`; UsageError when it is neither."""
    name, colon, column = text.partition(":")
    if text == "count" or (colon and column and name in GROUP_NUMERIC):
        return name, (column if colon else None)
    raise UsageError("group: bad aggregate %r (use count, sum:COLUMN, min:COLUMN, max:COLUMN or mean:COLUMN)" % text)


def cmd_group(args, opts):
